const films = [{"title": "It’s a Wonderful Life", "year": 1946, "hook": "The tallest order in Bedford Falls is finding a way to tell one man what he means to an entire town.", "quotes": ["Zuzu's petals", "Hot dog!", "There they are!"], "trivia": ["The film began as Philip Van Doren Stern’s short story The Greatest Gift, which he had printed as a Christmas greeting.", "George's snowy streets were filmed on a studio backlot. The production used an artificial snow mixture that let the actors speak while it fell.", "Frank Capra made the film through Liberty Films. It earned five Academy Award nominations, including Best Picture."], "source": "https://en.wikipedia.org/wiki/It%27s_a_Wonderful_Life", "quoteSource": "https://www.springfieldspringfield.co.uk/movie_script.php?movie=its-a-wonderful-life"}, {"title": "Scrooge", "year": 1970, "hook": "Before one London night is through, a whole street will be singing about the man who used to collect its debts.", "quotes": ["Humbug!", "Marley?", "Two pounds seven and six"], "trivia": ["The set builders reused scenery from Oliver! to reconstruct Victorian London at Shepperton Studios.", "Ronald Searle illustrated the opening titles. His painted caricatures introduce the world of the film before the actors appear.", "Albert Finney was in his thirties during filming. Makeup allowed him to play both elderly Scrooge and his younger self."], "source": "https://en.wikipedia.org/wiki/Scrooge_(1970_film)", "quoteSource": "https://www.springfieldspringfield.co.uk/movie_script.php?movie=scrooge-1970"}, {"title": "A Charlie Brown Christmas", "year": 1965, "hook": "A nickel drops, a piano starts swinging, and a scrawny sapling gets the grandest entrance in the school play.", "quotes": ["Good grief.", "Five cents, please.", "This is ridiculous."], "trivia": ["Bill Melendez directed the special and supplied Snoopy’s voice. He had already worked with the Peanuts characters in television commercials.", "Vince Guaraldi's jazz trio gave the broadcast a piano-led score. Skating is one of Guaraldi’s compositions for the special.", "Producer Lee Mendelson wrote the words to Christmas Time Is Here. The Christmas special aired without a recorded laugh track."], "source": "https://www.peanuts.com/classic-holiday-specials", "quoteSource": "https://www.springfieldspringfield.co.uk/movie_script.php?movie=a-charlie-brown-christmas"}, {"title": "Rudolph the Red-Nosed Reindeer", "year": 1964, "hook": "A prospector, a would-be dentist and a reindeer with a luminous nose make a surprisingly good traveling party.", "quotes": ["I'm cute!", "Bumbles bounce!", "A dentist?!"], "trivia": ["The adventure was developed in New York, but the animation was photographed in Japan and many of the voices were recorded in Toronto.", "Rudolph appeared in Robert L. May’s booklet before Johnny Marks turned the story into a song. The television special draws on both.", "The original American broadcast ran on NBC in December 1964 under the sponsorship of General Electric."], "source": "https://en.wikipedia.org/wiki/Rudolph_the_Red-Nosed_Reindeer_(TV_special)", "quoteSource": "https://www.springfieldspringfield.co.uk/movie_script.php?movie=rudolph-the-red-nosed-reindeer"}, {"title": "How the Grinch Stole Christmas!", "year": 1966, "hook": "High above Whoville, one very small dog and one very full sleigh are about to test the weight of Christmas.", "quotes": ["Oh, the noise.", "two sizes too small", "Santy Claus"], "trivia": ["Boris Karloff is both the storyteller and the Grinch’s speaking voice. The bass singing the Grinch’s signature number is Thurl Ravenscroft.", "Chuck Jones and Dr. Seuss had worked together on animated training films during World War II, long before adapting the Grinch.", "The special aired in color in 1966. Jones and Seuss settled on green for a character whose original book appearance did not establish that familiar skin color."], "source": "https://en.wikipedia.org/wiki/How_the_Grinch_Stole_Christmas!_(TV_special)", "quoteSource": "https://www.springfieldspringfield.co.uk/movie_script.php?movie=how-the-grinch-stole-christmas-1966"}, {"title": "Frosty the Snowman", "year": 1969, "hook": "All it takes is a magician losing his hat for the children in one schoolyard to acquire a very unusual friend.", "quotes": ["Happy Birthday!", "Messy messy messy.", "Busy busy busy!"], "trivia": ["Rankin and Bass wanted the characters to resemble a Christmas card. Greeting-card artist Paul Coker Jr. designed the characters and backgrounds.", "Mushi Production in Tokyo provided the hand-drawn animation, giving Frosty a different look from Rankin/Bass’s puppet specials.", "The title song predates the television special. Its writers were Walter Rollins and Steve Nelson."], "source": "https://en.wikipedia.org/wiki/Frosty_the_Snowman_(TV_special)", "quoteSource": "https://www.springfieldspringfield.co.uk/movie_script.php?movie=frosty-the-snowman"}, {"title": "Santa Claus Is Comin’ to Town", "year": 1970, "hook": "The mail carrier has quite a story about how a basket, a bag of toys and a schoolteacher changed Sombertown.", "quotes": ["I'll call you Topper.", "No toys", "Now, now, cut that out!"], "trivia": ["Fred Astaire voices the mail carrier S. D. Kluger, while Mickey Rooney voices the young Kris Kringle.", "The animators used stop-motion puppets for the film, a process marketed by Rankin/Bass under the name Animagic.", "The title song was written by J. Fred Coots and Haven Gillespie decades before the special debuted on American television in 1970."], "source": "https://en.wikipedia.org/wiki/Santa_Claus_Is_Comin%27_to_Town_(TV_special)", "quoteSource": "https://www.springfieldspringfield.co.uk/movie_script.php?movie=santa-claus-is-comin-to-town"}, {"title": "The Year Without a Santa Claus", "year": 1974, "hook": "Southtown wants snow, Santa wants a day in bed, and two brothers cannot agree on a single degree.", "quotes": ["I'm Mrs. Claus.", "A holiday? Nonsense!", "Load up the sleigh!"], "trivia": ["Phyllis McGinley’s 1956 book supplied the premise for the 1974 television special.", "Shirley Booth, who played Mrs. Claus and narrated the story, made this her final acting performance.", "Mickey Rooney returned as Santa for A Miser Brothers’ Christmas in 2008, and George S. Irving again supplied Heat Miser’s voice."], "source": "https://en.wikipedia.org/wiki/The_Year_Without_a_Santa_Claus", "quoteSource": "https://www.springfieldspringfield.co.uk/movie_script.php?movie=the-year-without-a-santa-claus"}, {"title": "A Christmas Story", "year": 1983, "hook": "An icy flagpole, a glowing leg lamp and one boy’s Christmas wish turn an Indiana neighborhood into Ralphie Parker’s whole universe.", "quotes": ["Oh, fudge!", "A major award!", "Fra-gee-lay."], "trivia": ["Jean Shepherd adapted stories he had told on the radio and supplied the grown-up Ralphie’s narration.", "Cleveland’s Higbee’s department store appears on screen as the store Ralphie visits.", "Director Bob Clark appears on screen as a neighbor admiring the Old Man’s illuminated prize."], "source": "https://en.wikipedia.org/wiki/A_Christmas_Story"}, {"title": "National Lampoon’s Christmas Vacation", "year": 1989, "hook": "Clark Griswold strings up enough lights for the whole neighborhood and still cannot see the family disasters coming.", "quotes": ["Play ball!", "Where’s the Tylenol?", "Squirrel!"], "trivia": ["John Hughes adapted his magazine story Christmas ’59 for the screenplay.", "Mae Questel, once a voice of Betty Boop, plays Aunt Bethany.", "The snowy opening was filmed in Colorado, even though the Griswolds live near Chicago."], "source": "https://en.wikipedia.org/wiki/National_Lampoon%27s_Christmas_Vacation"}, {"title": "Home Alone", "year": 1990, "hook": "A house big enough for a dozen McCallisters feels very different when the smallest one wakes up there alone.", "quotes": ["Kevin!", "I made my family disappear.", "Keep the change."], "trivia": ["The Chicago suburban house used for exterior scenes stands in Winnetka, Illinois.", "John Williams received Oscar nominations for his score and the song Somewhere in My Memory.", "The vintage-looking gangster movie Kevin watches was created especially for Home Alone."], "source": "https://en.wikipedia.org/wiki/Home_Alone"}, {"title": "Home Alone 2: Lost in New York", "year": 1992, "hook": "Kevin makes the wrong flight and discovers that a recording machine and his dad’s wallet can open a very grand hotel door.", "quotes": ["Merry Christmas, ya filthy animal.", "Credit card?", "Two turtle doves."], "trivia": ["Chris Columbus directed both of the first two Home Alone films, with John Hughes writing both scripts.", "John Williams returned as composer and collaborated with Leslie Bricusse on Christmas Star.", "New York location filming included Rockefeller Center and the original World Trade Center."], "source": "https://en.wikipedia.org/wiki/Home_Alone_2:_Lost_in_New_York"}, {"title": "The Santa Clause", "year": 1994, "hook": "One snowy thump on Scott Calvin’s roof turns a strained father-son Christmas into the beginning of a very peculiar job.", "quotes": ["Believing is seeing.", "My own recipe.", "Shaken, not stirred."], "trivia": ["Oakville, Ontario, stood in for the Illinois town where Scott lives.", "The production used reindeer from the Toronto Zoo.", "After Eric Lloyd injured his teeth on a day off, the production used false teeth and adjusted some of his dialogue."], "source": "https://en.wikipedia.org/wiki/The_Santa_Clause"}, {"title": "Jingle All the Way", "year": 1996, "hook": "In Minneapolis on Christmas Eve, the one thing every parent seems to have forgotten is the same Turbo-Man doll.", "quotes": ["It’s Turbo time!", "Put that cookie down!", "Nobody likes you, Booster."], "trivia": ["The crew filmed in the Twin Cities, including the Mall of America, before moving production to California.", "The climactic Minneapolis parade was filmed in California.", "A retail Turbo-Man figure was produced to go with the film, turning the invented TV hero into a real toy."], "source": "https://en.wikipedia.org/wiki/Jingle_All_the_Way"}, {"title": "Elf", "year": 2003, "hook": "Follow a human in pointy shoes from Santa’s workshop to Manhattan, where syrup belongs on spaghetti and singing counts as fuel.", "quotes": ["Santa! I know him!", "Son of a nutcracker!", "Smiling’s my favorite."], "trivia": ["The filmmakers used forced perspective to make Buddy look enormous beside his elf classmates.", "Jon Favreau added singing for Jovie after learning that Zooey Deschanel could sing.", "Favreau appears in front of the camera as the doctor who tests whether Walter is Buddy’s father."], "source": "https://en.wikipedia.org/wiki/Elf_(film)"}, {"title": "The Polar Express", "year": 2004, "hook": "When a steam train stops outside a boy’s house on Christmas Eve, his golden ticket is only the beginning of what he must learn to hear.", "quotes": ["All aboard!", "Tickets, please.", "I believe."], "trivia": ["Tom Hanks played several roles, including the conductor, the hobo and Santa.", "Chris Van Allsburg’s illustrated picture book appeared in 1985, nearly two decades before the film.", "Believe, written by Glen Ballard and Alan Silvestri, was nominated for the Academy Award for original song."], "source": "https://en.wikipedia.org/wiki/The_Polar_Express_(film)"}, {"title": "Die Hard", "year": 1988, "hook": "When an airport teddy bear and a limousine pull up to Nakatomi Plaza, Christmas Eve has barely begun for John McClane.", "quotes": ["Welcome to the party, pal!", "Glass?", "Happy trails, Hans."], "trivia": ["Nakatomi Plaza has a real address under a different name. The production filmed in and around Fox Plaza in Los Angeles.", "The movie began as an adaptation of Roderick Thorp’s novel Nothing Lasts Forever.", "Christmas on screen arrived in July for American moviegoers when Die Hard opened in 1988."], "source": "https://en.wikipedia.org/wiki/Die_Hard", "quoteSource": "https://www.springfieldspringfield.co.uk/movie_script.php?movie=die-hard"}, {"title": "Last Christmas", "year": 2019, "hook": "London glows above the shop windows while a young woman in elf shoes learns to raise her eyes.", "quotes": ["Look up.", "Elf and safety?", "Lazy the Elf"], "trivia": ["Emma Thompson helped write the screenplay and also appears as Kate’s mother, Petra.", "Wham!’s Andrew Ridgeley has a small on-screen appearance in the audience at the shelter show.", "The soundtrack includes This Is How, a George Michael recording released after his death."], "source": "https://www.universalpictures.com/movies/last-christmas", "quoteSource": "https://www.springfieldspringfield.co.uk/movie_script.php?movie=last-christmas"}, {"title": "The Little Drummer Boy", "year": 1968, "hook": "A small drum keeps time for three dancing animals on a road that ends at the manger.", "quotes": ["My very own drum!", "All these people!", "The royal caravan!"], "trivia": ["Greer Garson’s voice guides the audience through Aaron’s story, while Teddy Eccles speaks for Aaron.", "The special reached Canadian television four days before its first American network broadcast.", "The Vienna Boys’ Choir sings the song that gave the special its title."], "source": "https://en.wikipedia.org/wiki/The_Little_Drummer_Boy_(TV_special)", "quoteSource": "https://transcripts.foreverdreaming.org/viewtopic.php?t=54011"}, {"title": "Dr. Seuss’ How the Grinch Stole Christmas", "year": 2000, "hook": "Remember Whoville as a whole town that looks bent by hand, with one green holdout high above it.", "quotes": ["Hate, hate, hate.", "Double hate.", "Loathe entirely!"], "trivia": ["Rick Baker and Gail Rowell-Ryan won the film’s Academy Award for makeup.", "Anthony Hopkins narrates Ron Howard’s live-action version of the Dr. Seuss book.", "Taylor Momsen played Cindy Lou Who opposite Jim Carrey’s Grinch."], "source": "https://www.universalpictures.com/movies/dr-seuss-how-the-grinch-stole-christmas", "quoteSource": "https://www.springfieldspringfield.co.uk/movie_script.php?movie=how-the-grinch-stole-christmas"}, {"title": "Olive, the Other Reindeer", "year": 1999, "hook": "A dog hears her own name on the radio, and suddenly the bus to the North Pole sounds perfectly sensible.", "quotes": ["I know reindeer.", "Counterfeit watches again?", "Denise who?"], "trivia": ["Drew Barrymore both voiced Olive and served as an executive producer.", "The special adapted a picture book written by Vivian Walsh and illustrated by J. Otto Seibold.", "The Fox broadcast shared its December 1999 evening with Futurama, another series associated with Matt Groening."], "source": "https://en.wikipedia.org/wiki/Olive,_the_Other_Reindeer", "quoteSource": "https://www.springfieldspringfield.co.uk/movie_script.php?movie=olive-the-other-reindeer"}, {"title": "Christmas with the Kranks", "year": 2004, "hook": "One unlit house on Hemlock Street is enough to set an entire neighborhood knocking.", "quotes": ["Free Frosty!", "Whatever you say, Luther.", "Merry Christmas, Nora."], "trivia": ["The story came from John Grisham’s 2001 novel Skipping Christmas. Chris Columbus wrote the screen adaptation.", "The filmmakers built Hemlock Street on a former aircraft-factory site in Downey, California.", "Although the story takes place near Chicago, Nora’s supermarket hunt was filmed in Glendale, California."], "source": "https://www.sonypictures.com/movies/christmaswiththekranks", "quoteSource": "https://www.springfieldspringfield.co.uk/movie_script.php?movie=christmas-with-the-kranks"}, {"title": "The Santa Clause 2", "year": 2002, "hook": "Eight years after Scott put on the suit, one more line of fine print sends him back into the dating pool.", "quotes": ["Tiny hammers.", "the Mrs clause", "The de-Santification?"], "trivia": ["Tim Allen plays two Santas in the sequel, the increasingly human Scott and the conspicuously plastic replacement.", "Michael Lembeck directed the film, his first feature as a director after years of television work.", "Elizabeth Mitchell joined returning cast members Eric Lloyd, Wendy Crewson and David Krumholtz as school principal Carol Newman."], "source": "https://d23.com/a-to-z/santa-clause-2-the-film/", "quoteSource": "https://www.springfieldspringfield.co.uk/movie_script.php?movie=the-santa-clause-2"}, {"title": "Office Christmas Party", "year": 2016, "hook": "At Zenotek, a carefully budgeted holiday mixer lasts about as long as the first round of drinks.", "quotes": ["holiday mixer", "Do you party?", "a black belt in partying"], "trivia": ["Will Speck and Josh Gordon shared directing duties on the film.", "The movie used locations in both Georgia and Chicago. Production went from Atlanta to Chicago and then to Hiram, Georgia.", "Chicago Bulls player Jimmy Butler turns up at the fictional Chicago office party as himself."], "source": "https://www.paramountpictures.com/movies/office-christmas-party", "quoteSource": "https://www.springfieldspringfield.co.uk/movie_script.php?movie=office-christmas-party"}];
